def extract(grid, colors):
    h,w = grid.shape
    result = {}
    seen = np.zeros((h,w), dtype=bool)
    for r in range(h):
        for c in range(w):
            v = grid[r,c]
            if v not in colors or seen[r,c]: continue
            cells = []
            stack = [(r,c)]
            while stack:
                y,x = stack.pop()
                if seen[y][x] or grid[y][x] != v: continue
                seen[y][x] = True
                cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
