                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx] == v:
                        stack.append((ny,nx))
            bbox = sorted(cells, key=lambda p:(p[1],p[0]))  # by col then row
            rs = [c for r,c in cells]; cs = [r for r,c in cells]
