import os, re, numpy as np
def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
In = np.array(G['Demo pair 1 input'])
Out = np.array(G['Demo pair 1 output'])
Ti = np.array(G['Test input'])

# Find connected components of non-background cells (4-connectivity), background is most common color
def find_components(grid):
    h, w = grid.shape
    seen = np.zeros_like(grid, dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r,c] != 2 and not seen[r,c]:
                stack = [(r,c)]
                cells = []
                while stack:
                    y,x = stack.pop()
                    if seen[y,x] or grid[y,x] == 2: continue
                    seen[y,x] = True
                    cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx = y+dy, x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny,nx] and grid[ny,nx]!=2:
                            stack.append((ny,nx))
                xs = [c for _ , c in cells]; ys = [r for _ , r in cells]
                vals = set(grid[x,y] for x,y in cells)
                comps.append({
                    'cells': cells,
                    'color': sorted(vals)[0],
                    'bbox': (min(ys), min(xs), max(ys), max(xs)),
                    'count': len(cells)
                })
    return comps

